using System;
using System.Drawing;
using System.Windows.Forms;
using System.Threading;

namespace BulkStoreInstallerCompanion
{
    
    public static class Resources {
        public static string LogoPngB64 = "";
        public static string LogoIcoB64 = "";
    }
    
    public class WizardForm : Form
    {
        private Panel bottomPanel;
        private Button btnNext;
        private Button btnBack;
        private Button btnCancel;
        private Label separator;

        private Panel[] pages;
        private int currentPageIndex = 0;

        // Controls for specific pages
        private ProgressBar progressBar;
        private Label progressLabel;
        private Label extractingLabel;
        private TextBox txtPath;
        private System.Windows.Forms.Timer installTimer;
        private int installProgress = 0;

        public WizardForm()
        {
            this.Text = "Setup - BulkStoreInstaller Companion";
            this.Size = new Size(500, 380);
            this.StartPosition = FormStartPosition.CenterScreen;
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = false;
            this.Font = new Font("Segoe UI", 9f);
            this.BackColor = Color.White;
            try {
                byte[] icoBytes = Convert.FromBase64String(Resources.LogoIcoB64);
                using (var ms = new System.IO.MemoryStream(icoBytes)) {
                    this.Icon = new Icon(ms);
                }
            } catch { }


            InitializeWizardFrame();
            InitializePages();
            
            ShowPage(0);
        }

        private void InitializeWizardFrame()
        {
            bottomPanel = new Panel();
            bottomPanel.Dock = DockStyle.Bottom;
            bottomPanel.Height = 50;
            bottomPanel.BackColor = SystemColors.Control;
            this.Controls.Add(bottomPanel);

            separator = new Label();
            separator.BorderStyle = BorderStyle.Fixed3D;
            separator.Height = 2;
            separator.Dock = DockStyle.Top;
            bottomPanel.Controls.Add(separator);

            btnCancel = new Button();
            btnCancel.Text = "Cancel";
            btnCancel.Size = new Size(75, 25);
            btnCancel.Location = new Point(this.ClientSize.Width - 85, 12);
            btnCancel.Click += (s, e) => { if(MessageBox.Show("Setup is not complete. If you exit now, the program will not be installed.\n\nExit Setup?", "Exit Setup", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes) this.Close(); };
            bottomPanel.Controls.Add(btnCancel);

            btnNext = new Button();
            btnNext.Text = "Next >";
            btnNext.Size = new Size(75, 25);
            btnNext.Location = new Point(this.ClientSize.Width - 175, 12);
            btnNext.Click += BtnNext_Click;
            bottomPanel.Controls.Add(btnNext);

            btnBack = new Button();
            btnBack.Text = "< Back";
            btnBack.Size = new Size(75, 25);
            btnBack.Location = new Point(this.ClientSize.Width - 250, 12);
            btnBack.Click += BtnBack_Click;
            bottomPanel.Controls.Add(btnBack);
        }

        private void InitializePages()
        {
            pages = new Panel[4];
            
            // Page 0: Welcome
            pages[0] = new Panel { Dock = DockStyle.Fill, BackColor = Color.White };
            Label lblWelcomeTitle = new Label { Text = "Welcome to the BulkStoreInstaller Companion Setup Wizard", Font = new Font("Segoe UI", 12f, FontStyle.Bold), Location = new Point(160, 20), AutoSize = true };
            Label lblWelcomeDesc = new Label { Text = "This will install BulkStoreInstaller Companion version 1.0.0 on your computer.\n\nIt is recommended that you close all other applications before continuing.\n\nClick Next to continue, or Cancel to exit Setup.", Location = new Point(160, 70), Size = new Size(300, 150) };
            
            // Draw a fake sidebar image area
            
            Panel sidebar = new Panel { Width = 140, Dock = DockStyle.Left, BackColor = Color.FromArgb(41, 128, 185) };
            
            // Add Logo to sidebar
            try {
                byte[] imgBytes = Convert.FromBase64String(Resources.LogoPngB64);
                using (var ms = new System.IO.MemoryStream(imgBytes)) {
                    var logoImg = System.Drawing.Image.FromStream(ms);
                    PictureBox pb = new PictureBox {
                        Image = logoImg,
                        SizeMode = PictureBoxSizeMode.Zoom,
                        Width = 100,
                        Height = 100,
                        BackColor = Color.Transparent
                    };
                    pb.Location = new Point((sidebar.Width - pb.Width) / 2, (this.ClientSize.Height - pb.Height) / 2 - 30);
                    sidebar.Controls.Add(pb);
                }
            } catch (Exception ex) {
                // Ignore if invalid
            }

            pages[0].Controls.Add(lblWelcomeTitle);
            pages[0].Controls.Add(lblWelcomeDesc);
            pages[0].Controls.Add(sidebar);

            // Page 1: Destination
            pages[1] = new Panel { Dock = DockStyle.Fill, BackColor = SystemColors.Control };
            Panel header1 = new Panel { Height = 60, Dock = DockStyle.Top, BackColor = Color.White };
            header1.Controls.Add(new Label { Text = "Select Destination Location", Font = new Font("Segoe UI", 9f, FontStyle.Bold), Location = new Point(20, 10), AutoSize = true });
            header1.Controls.Add(new Label { Text = "Where should BulkStoreInstaller Companion be installed?", Location = new Point(30, 30), AutoSize = true });
            header1.Controls.Add(new Label { BorderStyle = BorderStyle.Fixed3D, Height = 2, Dock = DockStyle.Bottom });
            pages[1].Controls.Add(header1);
            
            pages[1].Controls.Add(new Label { Text = "Setup will install BulkStoreInstaller Companion into the following folder.", Location = new Point(20, 80), AutoSize = true });
            string defaultDir = System.IO.Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.LocalApplicationData), @"Programs\BulkStoreInstaller Companion");
            txtPath = new TextBox { Text = defaultDir, Location = new Point(20, 110), Width = 340 };
            Button btnBrowse = new Button { Text = "Browse...", Location = new Point(370, 109), Size = new Size(75, 23) };
            btnBrowse.Click += (s, e) => {
                using (FolderBrowserDialog fbd = new FolderBrowserDialog()) {
                    fbd.Description = "Select Destination Location";
                    if (fbd.ShowDialog() == DialogResult.OK) {
                        txtPath.Text = System.IO.Path.Combine(fbd.SelectedPath, "BulkStoreInstaller Companion");
                    }
                }
            };
            pages[1].Controls.Add(txtPath);
            pages[1].Controls.Add(btnBrowse);
            pages[1].Controls.Add(new Label { Text = "At least 15.4 MB of free disk space is required.", Location = new Point(20, 150), AutoSize = true });

            // Page 2: Installing
            pages[2] = new Panel { Dock = DockStyle.Fill, BackColor = SystemColors.Control };
            Panel header2 = new Panel { Height = 60, Dock = DockStyle.Top, BackColor = Color.White };
            header2.Controls.Add(new Label { Text = "Installing", Font = new Font("Segoe UI", 9f, FontStyle.Bold), Location = new Point(20, 10), AutoSize = true });
            header2.Controls.Add(new Label { Text = "Please wait while Setup installs BulkStoreInstaller Companion on your computer.", Location = new Point(30, 30), AutoSize = true });
            header2.Controls.Add(new Label { BorderStyle = BorderStyle.Fixed3D, Height = 2, Dock = DockStyle.Bottom });
            pages[2].Controls.Add(header2);

            progressLabel = new Label { Text = "Extracting files...", Location = new Point(20, 80), AutoSize = true };
            extractingLabel = new Label { Text = @"C:\Program Files\BulkStoreInstaller Companion\companion.exe", Location = new Point(20, 100), AutoSize = true, ForeColor = Color.Gray };
            progressBar = new ProgressBar { Location = new Point(20, 130), Size = new Size(425, 20) };
            pages[2].Controls.Add(progressLabel);
            pages[2].Controls.Add(extractingLabel);
            pages[2].Controls.Add(progressBar);

            // Page 3: Completed
            pages[3] = new Panel { Dock = DockStyle.Fill, BackColor = Color.White };
            Label lblDoneTitle = new Label { Text = "Completing the BulkStoreInstaller Companion Setup Wizard", Font = new Font("Segoe UI", 12f, FontStyle.Bold), Location = new Point(160, 20), Size = new Size(300, 50) };
            Label lblDoneDesc = new Label { Text = "Setup has finished installing BulkStoreInstaller Companion on your computer. The application may be launched by selecting the installed shortcuts.\n\nClick Finish to exit Setup.", Location = new Point(160, 80), Size = new Size(300, 100) };
            CheckBox chkLaunch = new CheckBox { Text = "Launch BulkStoreInstaller Companion", Checked = true, Location = new Point(160, 180), AutoSize = true };
            
            Panel sidebar3 = new Panel { Width = 140, Dock = DockStyle.Left, BackColor = Color.FromArgb(41, 128, 185) };
            pages[3].Controls.Add(lblDoneTitle);
            pages[3].Controls.Add(lblDoneDesc);
            pages[3].Controls.Add(chkLaunch);
            pages[3].Controls.Add(sidebar3);

            foreach(var page in pages)
            {
                page.Visible = false;
                this.Controls.Add(page);
                page.BringToFront();
            }
        }

        private void ShowPage(int index)
        {
            if (currentPageIndex >= 0 && currentPageIndex < pages.Length)
                pages[currentPageIndex].Visible = false;

            currentPageIndex = index;
            pages[currentPageIndex].Visible = true;

            btnBack.Enabled = (index > 0 && index != 2 && index != 3);
            
            if (index == 0)
            {
                btnNext.Text = "Next >";
                btnNext.Enabled = true;
                btnCancel.Enabled = true;
            }
            else if (index == 1)
            {
                btnNext.Text = "Install";
                btnNext.Enabled = true;
                btnCancel.Enabled = true;
            }
            else if (index == 2)
            {
                btnNext.Enabled = false;
                btnBack.Enabled = false;
                btnCancel.Enabled = false;
                StartInstall();
            }
            else if (index == 3)
            {
                btnNext.Text = "Finish";
                btnNext.Enabled = true;
                btnBack.Visible = false;
                btnCancel.Enabled = false;
            }
        }

        private void BtnNext_Click(object sender, EventArgs e)
        {
            if (currentPageIndex == 3)
            {
                this.Close(); // Finish
                return;
            }
            ShowPage(currentPageIndex + 1);
        }

        private void BtnBack_Click(object sender, EventArgs e)
        {
            ShowPage(currentPageIndex - 1);
        }

        private void StartInstall()
        {
            installProgress = 0;
            progressBar.Value = 0;
            
            installTimer = new System.Windows.Forms.Timer();
            installTimer.Interval = 20;
            installTimer.Tick += InstallTimer_Tick;
            installTimer.Start();
        }

        private string[] files = new string[] {
            "companion.exe", "uninstall.exe", "Newtonsoft.Json.dll", "config.json", 
            "locales\\en-US.pak", "resources\\app.asar", "winget_integration.dll",
            "icudtl.dat", "v8_context_snapshot.bin", 
            "Registering protocol handler...", "Creating shortcuts...", "Finishing installation..."
        };

        private void InstallTimer_Tick(object sender, EventArgs e)
        {
            installProgress += 1;
            string installPath = txtPath.Text;
            
            if (installProgress <= 100)
            {
                // Fix for WinForms ProgressBar animation lag
                if (installProgress < 100) {
                    progressBar.Value = installProgress + 1;
                    progressBar.Value = installProgress;
                } else {
                    progressBar.Value = installProgress;
                }
                
                int fileIndex = (int)((installProgress / 100.0) * (files.Length - 1));
                string currentFile = files[Math.Min(fileIndex, files.Length - 1)];
                
                if (currentFile.StartsWith("Registering") || currentFile.StartsWith("Creating") || currentFile.StartsWith("Finishing")) {
                    extractingLabel.Text = currentFile;
                } else {
                    extractingLabel.Text = "Extracting: " + System.IO.Path.Combine(installPath, currentFile);
                    
                    try {
                        string fullPath = System.IO.Path.Combine(installPath, currentFile);
                        string dir = System.IO.Path.GetDirectoryName(fullPath);
                        if (!System.IO.Directory.Exists(dir)) {
                            System.IO.Directory.CreateDirectory(dir);
                        }
                        
                        if (currentFile.ToLower() == "companion.exe" || currentFile.ToLower() == "uninstall.exe") {
                            System.IO.File.Copy(Application.ExecutablePath, fullPath, true);
                        } else if (!System.IO.File.Exists(fullPath)) {
                            System.IO.File.WriteAllText(fullPath, "Dummy file for BulkStoreInstaller Companion setup.");
                        }
                    } catch { }
                }
            }
            else if (installProgress > 115) // Give a slight pause at 100%
            {
                installTimer.Stop();
                CreateUninstallerAndRegistry(txtPath.Text);
                ShowPage(3);
            }
        }

        private void CreateUninstallerAndRegistry(string installPath)
        {
            try
            {
                string uninstallExe = System.IO.Path.Combine(installPath, "uninstall.exe");
                if (!System.IO.File.Exists(uninstallExe))
                {
                    System.IO.File.Copy(Application.ExecutablePath, uninstallExe, true);
                }

                string uninstallKey = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\BulkStoreInstallerCompanion";
                
                // 1. CurrentUser registry (Always works without admin permissions)
                try
                {
                    using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.CreateSubKey(uninstallKey))
                    {
                        if (key != null)
                        {
                            key.SetValue("DisplayName", "BulkStoreInstaller Companion");
                            key.SetValue("DisplayVersion", "1.0.0");
                            key.SetValue("Publisher", "BulkStoreInstaller");
                            key.SetValue("DisplayIcon", System.IO.Path.Combine(installPath, "companion.exe"));
                            key.SetValue("UninstallString", "\"" + uninstallExe + "\"");
                            key.SetValue("InstallLocation", installPath);
                        }
                    }
                }
                catch { }

                // 2. LocalMachine registry (If elevated)
                try
                {
                    using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.LocalMachine.CreateSubKey(uninstallKey))
                    {
                        if (key != null)
                        {
                            key.SetValue("DisplayName", "BulkStoreInstaller Companion");
                            key.SetValue("DisplayVersion", "1.0.0");
                            key.SetValue("Publisher", "BulkStoreInstaller");
                            key.SetValue("DisplayIcon", System.IO.Path.Combine(installPath, "companion.exe"));
                            key.SetValue("UninstallString", "\"" + uninstallExe + "\"");
                            key.SetValue("InstallLocation", installPath);
                        }
                    }
                }
                catch { }
            }
            catch { }
        }

        [STAThread]
        static void Main(string[] args)
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            
            string exeName = System.IO.Path.GetFileName(Application.ExecutablePath).ToLower();
            bool isUninstallMode = (exeName == "uninstall.exe") || (args != null && Array.Exists(args, a => a.ToLower() == "/uninstall" || a.ToLower() == "-uninstall"));

            if (isUninstallMode) {
                DialogResult dr = MessageBox.Show(
                    "Are you sure you want to completely uninstall BulkStoreInstaller Companion and all of its components?",
                    "Uninstall BulkStoreInstaller Companion",
                    MessageBoxButtons.YesNo,
                    MessageBoxIcon.Question
                );

                if (dr == DialogResult.Yes) {
                    try {
                        Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\BulkStoreInstallerCompanion", false);
                    } catch { }

                    try {
                        Microsoft.Win32.Registry.LocalMachine.DeleteSubKeyTree(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\BulkStoreInstallerCompanion", false);
                    } catch { }

                    string installDir = AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');
                    
                    // Self-destruct via cmd script
                    try {
                        System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo() {
                            FileName = "cmd.exe",
                            Arguments = "/c timeout /t 1 /nobreak >nul & rmdir /s /q \"" + installDir + "\"",
                            WindowStyle = System.Diagnostics.ProcessWindowStyle.Hidden,
                            CreateNoWindow = true
                        });
                    } catch { }

                    MessageBox.Show(
                        "BulkStoreInstaller Companion was successfully uninstalled.",
                        "Uninstall Complete",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information
                    );
                }
                return;
            }

            if (exeName == "companion.exe") {
                MessageBox.Show("The app is already running in background.", "BulkStoreInstaller Companion", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            
            Application.Run(new WizardForm());
        }
    }
}
